    avatar: "/avatars/kianna-vaccaro.webp",
  },
];
export function RecentHiresCard({
  hires = RECENT_HIRES,
  total = 56,
  team = "Board team",
  className,
}: {
  hires?: RecentHire[];
  total?: number;
  team?: string;
  className?: string;
}) {
  const [page, setPage] = useState(0);
  const reduced = useReducedMotion();
  const pages = Math.ceil(hires.length / 4);
  return (
    <section
      className={cx(
        "relative flex h-[329px] min-w-0 flex-col rounded-2xl bg-background-secondary-default p-2",
        className,
      )}
    >
      <div className="flex items-start justify-between px-2 pt-2">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="text-body-medium text-text-secondary">Recent hires</p>
          <p className="whitespace-nowrap text-title-1-medium text-text-primary">{total}</p>
        </div>
        <span className="text-body-medium text-text-primary">{team}</span>
      </div>
      <AnimatePresence mode="wait" initial={false}>
        <motion.div
          key={page}
          initial={reduced ? false : { opacity: 0, y: 6, filter: "blur(2px)" }}
          animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
          exit={{ opacity: 0, y: -4 }}
          transition={{ duration: reduced ? 0 : 0.18 }}
          className="mt-[11px] grid flex-1 grid-cols-2 grid-rows-2 gap-2"
        >
          {hires.slice(page * 4, page * 4 + 4).map((hire) => (
            <div
              key={hire.name}
              className="flex min-w-0 flex-col items-start justify-between rounded-2lg bg-background-inner-default p-2.5 shadow-card"
            >
              <div className="flex w-full min-w-0 items-center gap-2">
                <Avatar
                  src={hire.avatar}
                  alt={hire.name}
                  initials={hire.name
                    .split(" ")
                    .map((s) => s[0])
                    .join("")}
                  size="lg"
                />
                <div className="flex min-w-0 flex-1 flex-col items-start justify-center">
                  <p className="w-full truncate text-body-medium text-text-primary">{hire.name}</p>
                  <p className="w-full truncate text-body-2-medium text-text-secondary">
                    {hire.joined}
                  </p>
                </div>
              </div>
              <p className="w-full truncate rounded-md bg-background-recent-hire-role px-1.5 py-1 text-center text-caption-1-medium text-text-secondary">
                {hire.role}
              </p>
            </div>
          ))}
        </motion.div>
      </AnimatePresence>
      <div className="mt-2 flex w-full items-center gap-2">
        <Button
          variant="secondary"
          size="small"
          className="flex-1"
          leadingIcon={RiArrowLeftLine}
          disabled={page === 0}
          onClick={() => setPage((p) => Math.max(0, p - 1))}
        >
          Previous
        </Button>
        <Button
          variant="secondary"
          size="small"
          className="flex-1"
          trailingIcon={RiArrowRightLine}
          disabled={page >= pages - 1}
          onClick={() => setPage((p) => Math.min(pages - 1, p + 1))}
        >
          Next
        </Button>
      </div>
    </section>
  );
}

"use client";

import {
  RiAddLine,
  RiCloseLine,
  RiFilter3Fill,
  RiGroupLine,
  RiHomeLine,
  RiMenuLine,
} from "@remixicon/react";
import { type ComponentType, type ReactNode, useEffect, useRef, useState } from "react";
import { Avatar } from "../../base/avatar/avatar";
import { Breadcrumb, BreadcrumbItem } from "../../base/breadcrumb/breadcrumb";
import { Button } from "../../base/buttons/button";
import { IconButton } from "../../base/buttons/icon-button";
import { cx } from "../../utils/cx";
import { NotificationBell } from "../app-shell/notification-bell";
import { DASHBOARD_NAV, DashboardSidebar } from "../dashboard/dashboard-sidebar";

export interface TemplateShellProps {
  title: string;
  heading?: string;
  selected?: string;
  action?: string;
  onAction?: () => void;
  actions?: ReactNode;
  children: ReactNode;
  contained?: boolean;
  className?: string;
  columnClassName?: string;
  hideHeader?: boolean;
  icon?: ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;
}

/** The floating navigation and 1300px content column shared by dashboard templates. */
export function TemplateShell({
  title,
  heading = title,
  selected = "home",
  action = "Create ticket",
  onAction,
  actions,
  children,
  contained,
  className,
  columnClassName,
  hideHeader,
  icon: Icon = RiHomeLine,
}: TemplateShellProps) {
  const [navOpen, setNavOpen] = useState(false);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const closeRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!navOpen) return;
    closeRef.current?.focus();
    const close = (event: KeyboardEvent) => {
      if (event.key === "Escape") setNavOpen(false);
    };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [navOpen]);
  const nav = [
    ...DASHBOARD_NAV,
    // The library intentionally adds its HR template to the reference navigation.
    { key: "hr", label: "HR Team", icon: RiGroupLine, href: "/templates/hr" },
  ];
  return (
    <div
      className={cx(
        "relative flex w-full bg-background-full",
        contained ? "h-full min-h-[600px] overflow-hidden" : "min-h-dvh",
        className,
      )}
    >
      <div
        className={cx(
          "hidden shrink-0 py-3 pl-3 lg:block",
          contained ? "h-full" : "sticky top-0 h-dvh",
        )}
      >
        <DashboardSidebar items={nav} selected={selected} />
      </div>
      {navOpen && (
        <div className={cx("inset-0 z-40 lg:hidden", contained ? "absolute" : "fixed")}>
          <button
            type="button"
            aria-label="Close navigation overlay"
            onClick={() => setNavOpen(false)}
            className="absolute inset-0 bg-background-modal-overlay backdrop-blur-sm"
          />
          <div className="relative h-full w-[284px] p-3">
            <DashboardSidebar
              mobile
              items={nav}
              selected={selected}
              onClose={() => setNavOpen(false)}
            />
          </div>
          <button
            type="button"
            ref={closeRef}
            onClick={() => setNavOpen(false)}
            aria-label="Close navigation"
            className="absolute top-5 left-[290px] rounded-full bg-background-primary-default p-2 text-text-primary"
          >
            <RiCloseLine className="size-5" />
          </button>
        </div>
      )}
      <main
        className={cx(
          "relative flex min-w-0 flex-1 justify-center bg-background-full p-3 sm:pt-6",
          contained && "overflow-y-auto",
        )}
      >
        <div className={cx("flex w-full max-w-[1300px] flex-col gap-4 pb-4", columnClassName)}>
          {/* The header has a 10px following gap; content rows remain 16px apart. */}
          {!hideHeader && (
            <header className="-mb-1.5 flex w-full flex-col gap-2">
              <Breadcrumb>
                <BreadcrumbItem href="/templates/dashboard">
                  <Avatar size="xs" color="blue" initials="B" />
                  Board team
                </BreadcrumbItem>
                <BreadcrumbItem href="/templates/ai-profile">
                  <Avatar size="xs" initials="M" />
                  Mertcan
                </BreadcrumbItem>
                <BreadcrumbItem current icon={Icon}>
                  {title}
                </BreadcrumbItem>
              </Breadcrumb>
              <div className="flex w-full flex-wrap items-end justify-between gap-2">
                <div className="flex min-w-0 items-center gap-1.5">
                  <IconButton
                    icon={RiMenuLine}
                    className="lg:hidden"
                    aria-label="Open navigation"
                    onClick={() => setNavOpen(true)}
                  />
                  <h1 className="px-1 text-title-2-medium text-text-primary">{heading}</h1>
                </div>
                <div className="flex flex-wrap items-center justify-end gap-2.5">
                  {actions !== undefined ? (
                    actions
                  ) : (
                    <>
                      <NotificationBell />
                      <Button
                        variant="secondary"
                        leadingIcon={RiFilter3Fill}
                        onClick={() => setFiltersOpen((open) => !open)}
                        aria-expanded={filtersOpen}
                      >
                        Filters
                      </Button>
                      {onAction && (
                        <Button leadingIcon={RiAddLine} onClick={onAction}>
                          {action}
                        </Button>
                      )}
                    </>
                  )}
                </div>
              </div>
              {filtersOpen && (
                <div className="flex items-center justify-between gap-3 rounded-xl bg-background-secondary-default px-4 py-3 text-body-regular text-text-secondary">
                  <span>
                    Use each chart’s period menu and the table filters below to explore this view.
                  </span>
                  <Button
                    size="small"
                    variant="secondary"
                    onClick={() => {
                      document
                        .querySelector("main section:last-child")
                        ?.scrollIntoView({ behavior: "smooth" });
                      setFiltersOpen(false);
                    }}
                  >
                    Go to records
                  </Button>
                </div>
              )}
            </header>
          )}
          {hideHeader && (
            <div className="lg:hidden">
              <IconButton
                icon={RiMenuLine}
                aria-label="Open navigation"
                onClick={() => setNavOpen(true)}
              />
            </div>
          )}
          {children}
        </div>
      </main>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};
const clientSnapshot = () => true;
const serverSnapshot = () => false;

/** Keep the first server/client render identical, then apply the user's motion preference. */
export function useHydratedReducedMotion(): boolean {
  const reduced = useReducedMotion();
  const hydrated = useSyncExternalStore(subscribe, clientSnapshot, serverSnapshot);
  return hydrated && reduced === true;
}
